function countComponents(moves, attacks) {
  return moves + attacks;
}

function countSubclasses(moves, attacks) {
  return moves * attacks;
}

function describe(name, behavior) {
  return name + " " + behavior();
}

function attackAll(name, behaviors) {
  return behaviors.map((b) => name + " " + b());
}

function countComponents3(a, b, c) {
  return a + b + c;
}

function countSubclasses3(a, b, c) {
  return a * b * c;
}

function makeCharacter(name, moves, attacks) {
  const run = (list) => list.map((b) => name + " " + b());
  return {
    move: () => run(moves),
    attack: () => run(attacks),
  };
}

function makeCharacter(name, parts) {
  return {
    perform: (axis) => (parts[axis] || []).map((b) => name + " " + b()),
  };
}

function costs(axes) {
  let composition = 0;
  let inheritance = 1;
  for (const n of axes) {
    composition += n;
    inheritance *= n;
  }
  return { composition, inheritance };
}

function addAttack(character, behavior) {
  return {
    name: character.name,
    attackBehaviors: [...character.attackBehaviors, behavior],
  };
}
